versions.variantCss:
.wemd-resource-list[data-variant="bytedance-resource-list"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 20px 24px;
  margin: 16px 0;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-title {
  color: var(--wemd-text-strong);
  font-size: 17px;
  font-weight: 700;
  margin: 0 0 4px 0;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-subtitle {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0 0 16px 0;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-items {
  margin: 0;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-item {
  display: flex;
  align-items: flex-start;
  padding: 10px 0;
  border-bottom: 1px solid var(--wemd-border-soft);
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-idx {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  background: var(--wemd-primary-light);
  color: var(--wemd-primary);
  font-size: 12px;
  font-weight: 700;
  border-radius: 4px;
  margin-right: 12px;
  flex-shrink: 0;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-icon {
  font-size: 18px;
  margin-right: 10px;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-main {
  flex: 1;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-item-title {
  color: var(--wemd-text-strong);
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 2px 0;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-item-desc {
  color: var(--wemd-text-soft);
  font-size: 12px;
  margin: 0;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-meta {
  color: var(--wemd-text-soft);
  font-size: 11px;
  margin: 2px 0 0 0;
}
.wemd-resource-list[data-variant="bytedance-resource-list"] .wemd-rl-tag {
  display: inline-block;
  background: var(--wemd-primary-light);
  color: var(--wemd-primary);
  font-size: 11px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
  margin-left: 8px;
}
